#include <stdio.h>
#include <stdlib.h>

static long long *slope_tree;
static long long *intercept_tree;
static int n;

static void add(long long *tree, int index, long long value) {
    for (; index <= n; index += index & -index) {
        tree[index] += value;
    }
}

static long long sum(long long *tree, int index) {
    long long result = 0;
    for (; index > 0; index -= index & -index) {
        result += tree[index];
    }
    return result;
}

static void range_add(long long *tree, int left, int right, long long value) {
    add(tree, left, value);
    if (right < n) {
        add(tree, right + 1, -value);
    }
}

int main(void) {
    int m;
    if (scanf("%d %d", &n, &m) != 2) {
        return 0;
    }

    slope_tree = calloc((size_t)n + 1, sizeof(long long));
    intercept_tree = calloc((size_t)n + 1, sizeof(long long));

    for (int q = 0; q < m; ++q) {
        int type, i;
        long long v;

        scanf("%d %d", &type, &i);

        if (type == 1) {
            scanf("%lld", &v);
            int right = i + (int)v - 1;
            if (right > n) right = n;

            range_add(slope_tree, i, right, -1);
            range_add(intercept_tree, i, right, v + i);
        } else if (type == 2) {
            scanf("%lld", &v);
            int left = i - (int)v + 1;
            if (left < 1) left = 1;

            range_add(slope_tree, left, i, 1);
            range_add(intercept_tree, left, i, v - i);
        } else {
            long long slope = sum(slope_tree, i);
            long long intercept = sum(intercept_tree, i);
            printf("%lld\n", slope * i + intercept);
        }
    }

    free(slope_tree);
    free(intercept_tree);
    return 0;
}
